ZTEST(rtio_work, test_work_req_submit_rejects_null_req)
{
	/* Initialize the dummy_iodev_sqe to prevent crashes if the
	 * rtio_work_req_submit function unexpectedly calls the handler
	 * with a NULL request. The test expects the handler NOT to be called.
	 */
	struct rtio_iodev_sqe dummy_iodev_sqe = {0};
	K_SEM_DEFINE(local_dummy_sem, 0, 1);

	/* Provide a valid semaphore for userdata in case work_handler is called.
	 * This prevents a segmentation fault from dereferencing uninitialized data.
	 */
	dummy_iodev_sqe.sqe.userdata = (void *)&local_dummy_sem;

	rtio_work_req_submit(NULL, &dummy_iodev_sqe, work_handler);

	/* The test expects work_handler not to be called when req is NULL. */
	zassert_equal(0, work_handler_called);
	zassert_equal(0, rtio_work_req_used_count_get());
}
